mapper.select:
select role_id
from sys_user_role
where tenant_id = #{tenantId}
  and user_id = #{userId}

select r.role_code
from sys_user_role ur
inner join sys_role r on r.id = ur.role_id
where ur.tenant_id = #{tenantId}
  and ur.user_id = #{userId}

mapper.delete:
delete from sys_user_role
where tenant_id = #{tenantId}
  and user_id = #{userId}

mapper.select:
select menu_id
from sys_role_menu
where tenant_id = #{tenantId}
  and role_id = #{roleId}

mapper.delete:
delete from sys_role_menu
where tenant_id = #{tenantId}
  and role_id = #{roleId}

mapper.select:
select count(distinct m.id)
from sys_user_role ur
inner join sys_role_menu rm on rm.role_id = ur.role_id and rm.tenant_id = ur.tenant_id
inner join sys_menu m on m.id = rm.menu_id and m.tenant_id = rm.tenant_id
where ur.tenant_id = #{tenantId}
  and ur.user_id = #{userId}
  and m.del_flag = '0'
  and m.status = 1
  and m.menu_type in ('CATALOG', 'MENU')
  and m.menu_scope = #{menuScope}
